// render: turns the permission model into the text of the four generated files.
// Where it fits: scripts/gen-permissions.mjs writes (or, with --check, compares) what this file returns.
// How it works: pure functions from the model to strings. Output is stable (fixed order, fixed layout), so a committed file
// only differs from a fresh one when a manifest, the legacy data or this renderer changed.
// Rules: no file access here. Every generated file starts with "GENERATED by scripts/gen-permissions.mjs. Do not edit."

export const GENERATED_FILES = {
  permissionsTs: "platform/src/tenancy/permissions.generated.ts",
  permissionsJs: "packages/config/src/permissions.generated.js",
  appsTs: "platform/src/tenancy/apps.generated.ts",
  appsJs: "packages/config/src/apps.generated.js",
};

const q = (s) => JSON.stringify(s);
const keyOf = (k) => (/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(k) ? k : q(k));

/** A compact, stable literal: short arrays and objects stay on one line, long ones are split one item per line. */
export function fmt(v, ind = 0, width = 210) {
  const pad = "  ".repeat(ind);
  if (v === null || v === undefined) return "null";
  if (typeof v === "string") return q(v);
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  if (Array.isArray(v)) {
    if (v.length === 0) return "[]";
    const one = `[${v.map((x) => fmt(x, 0)).join(", ")}]`;
    if (one.length + pad.length <= width && !one.includes("\n")) return one;
    return `[\n${v.map((x) => `${pad}  ${fmt(x, ind + 1)},\n`).join("")}${pad}]`;
  }
  const entries = Object.entries(v);
  if (entries.length === 0) return "{}";
  const one = `{ ${entries.map(([k, x]) => `${keyOf(k)}: ${fmt(x, 0)}`).join(", ")} }`;
  if (one.length + pad.length <= width && !one.includes("\n")) return one;
  return `{\n${entries.map(([k, x]) => `${pad}  ${keyOf(k)}: ${fmt(x, ind + 1)},\n`).join("")}${pad}}`;
}

const HEADER = "// GENERATED by scripts/gen-permissions.mjs. Do not edit.";

export function renderPermissions(model, legacy, ts) {
  const t = (type) => (ts ? type : "");
  const lines = [
    HEADER,
    `// What: the permission catalog, the role templates in the new names, and the old lists with the alias map (ACCESS.md sections 4.3, 6 and 8).`,
    `// Where it fits: ${ts ? "the servers (backend-core/src/domain/permissions.ts is a shim over this file)" : "the screens (shared/src/core/rbac.js is a shim over this file; import it as @sheetal/config/permissions)"}.`,
    `// How it works: written from apps/*/app.manifest.ts, platform/src/tenancy/platform.manifest.ts and platform/src/tenancy/legacy-v1.ts by \`npm run gen:permissions\`; \`-- --check\` fails when this file is out of date.`,
    `// Rules: data only. Change a manifest, then run the generator; never edit this file by hand.`,
    "",
  ];
  if (ts) lines.push(`import type { AliasMap, BusinessType, PermGroup, PermissionInfo, RoleTemplateV2 } from "./types.js";`, "");
  const types = model.allTypes;
  const defs = Object.fromEntries(types.map((k) => [k, { icon: model.defs[k].icon }]));
  lines.push(
    `export const BUSINESS_TYPE_IDS = ${fmt(types)}${ts ? " as const" : ""};`,
    `export const BUSINESS_TYPE_DEFS = ${fmt(defs)}${ts ? " as const" : ""};`,
    `export const APP_IDS${ts ? ": string[]" : ""} = ${fmt(model.sorted.map((m) => m.manifest.id))};`,
    "",
    `export const PERMISSION_CATALOG${t(": PermissionInfo[]")} = ${fmt(model.catalog)};`,
    "",
    `export const ROLE_TEMPLATES_V2${t(": Record<BusinessType, RoleTemplateV2[]>")} = ${fmt(model.roleTemplates)};`,
    `export const PLATFORM_ROLE_TEMPLATES_V2${t(": RoleTemplateV2[]")} = ${fmt(model.platformRoles)};`,
    "",
    `// Old name -> new names. Business and staff have separate maps because "roles.manage" means something different in each.`,
    `export const LEGACY_ALIASES${t(": AliasMap")} = ${fmt(legacy.LEGACY_ALIASES)};`,
    `export const LEGACY_PLATFORM_ALIASES${t(": AliasMap")} = ${fmt(legacy.LEGACY_PLATFORM_ALIASES)};`,
    "",
    `// Today's lists in the old names, unchanged: the shims export these so every old import keeps working.`,
    `export const LEGACY_BUSINESS_GROUPS${t(": PermGroup[]")} = ${fmt(legacy.LEGACY_BUSINESS_GROUPS)};`,
    `export const LEGACY_PLATFORM_GROUPS${t(": PermGroup[]")} = ${fmt(legacy.LEGACY_PLATFORM_GROUPS)};`,
    `export const LEGACY_TEMPLATES${t(": Record<BusinessType, [string, string[] | null][]>")} = ${fmt(legacy.LEGACY_TEMPLATES)};`,
    `export const LEGACY_PLATFORM_ROLES${t(": Record<string, string[]>")} = ${fmt(legacy.LEGACY_PLATFORM_ROLES)};`,
    "",
  );
  return lines.join("\n");
}

// What the screens need of an app (no events, jobs or models).
const SCREEN_KEYS = ["id", "kind", "name", "tagline", "icon", "category", "businessTypes", "editions", "trialDays", "limits", "menu", "approvals", "ai"];

export function renderApps(model, ts) {
  const apps = model.sorted.map((m) => m.manifest);
  const value = ts
    ? apps
    : apps.map((a) => ({
        ...Object.fromEntries(SCREEN_KEYS.map((k) => [k, a[k]])),
        permissions: a.permissions.map((p) => ({ id: p.id, label: p.label, scopes: p.scopes, default: p.default, group: p.group ?? null })),
        dependencies: { requires: a.dependencies.requires, optional: a.dependencies.optional },
        branchOwned: a.branchOwned,
      }));
  return [
    HEADER,
    `// What: the app registry, one entry per manifest (${ts ? "the whole manifest, for the servers" : "what the screens need: name, icon, menu, editions, permissions"}).`,
    `// Where it fits: ${ts ? "platform/core/apps.ts (later task) and the branch-delete check" : "the business shell menu (step 11) and the Marketplace (Phase 3); import it as @sheetal/config/apps"}.`,
    `// How it works: written from the manifests by \`npm run gen:permissions\`; \`-- --check\` fails when this file is out of date.`,
    `// Rules: data only. Change a manifest, then run the generator; never edit this file by hand.`,
    "",
    ...(ts ? [`import type { AppManifest } from "../core/manifest.js";`, ""] : []),
    `export const APPS${ts ? ": readonly AppManifest[]" : ""} = ${fmt(value)};`,
    "",
  ].join("\n");
}

export function renderAll(model, legacy) {
  return {
    [GENERATED_FILES.permissionsTs]: renderPermissions(model, legacy, true),
    [GENERATED_FILES.permissionsJs]: renderPermissions(model, legacy, false),
    [GENERATED_FILES.appsTs]: renderApps(model, true),
    [GENERATED_FILES.appsJs]: renderApps(model, false),
  };
}
